    result = match_entries(entries, statements, tolerance_cents=tolerance, period="2026-03")
    assert result.unmatched_entries == [], (
        "unmatched: %s" % [e.id for e in result.unmatched_entries]
    )
    assert len(result.pairs) == len(entries)

